import{_ as s,c as a,e,o as t}from"./app-DH3XcWdt.js";const p="/images/study-webrtc/19-sdk-layers-light.png",c="/images/study-webrtc/19-sdk-layers-dark.png",o="/images/study-webrtc/19-master-flow-light.png",i="/images/study-webrtc/19-master-flow-dark.png",l="/images/study-webrtc/19-gst-appsink-light.png",r="/images/study-webrtc/19-gst-appsink-dark.png",d="/images/study-webrtc/19-iot-credentials-light.png",u="/images/study-webrtc/19-iot-credentials-dark.png",k={};function v(m,n){return t(),a("div",null,n[0]||(n[0]=[e('<h1 id="디바이스-측-구현-kvs-c-sdk" tabindex="-1"><a class="header-anchor" href="#디바이스-측-구현-kvs-c-sdk"><span>디바이스 측 구현: KVS C SDK</span></a></h1><div class="hint-container info"><p class="hint-container-title">학습 목표</p><ul><li>KVS C SDK 저장소가 어떤 라이브러리와 서드파티 의존성으로 이뤄져 있는지, 주요 CMake 옵션이 무엇을 바꾸는지 설명할 수 있다.</li><li><code>kvsWebrtcClientMaster</code> 샘플이 자격증명 → 시그널링 클라이언트 → 오퍼 수신 → PeerConnection → <code>writeFrame</code>으로 이어지는 흐름을 C API 단위로 따라갈 수 있다.</li><li>GStreamer <code>appsink</code>로 하드웨어 인코더 출력을 SDK에 넘기는 구조와, 뷰어 수만큼 늘어나는 비용을 이해한다.</li><li>AWS IoT Credential Provider와 role alias로 디바이스에 장기 키 없이 임시 자격증명을 주고, Thing 이름 = 채널 이름으로 권한을 묶을 수 있다.</li><li>크로스 컴파일·메모리·로그 레벨을 조정해 임베디드 보드에 SDK를 올리고 현장에서 디버깅할 수 있다.</li></ul></div><p><a href="/study/webrtc/13-native-webrtc">13장</a>에서 브라우저 밖 WebRTC의 선택지로 libwebrtc·Pion·GStreamer <code>webrtcbin</code>·aiortc를 비교하고, KVS C SDK는 예고만 했다. 이 장은 그 KVS C SDK(<code>awslabs/amazon-kinesis-video-streams-webrtc-sdk-c</code>)로 농기계 카메라를 KVS 시그널링 채널의 master로 붙이는 방법을 다룬다. <a href="/study/webrtc/17-kvs-architecture">17장</a>·<a href="/study/webrtc/18-kvs-signaling-api">18장</a>에서 본 <code>DescribeSignalingChannel</code> → <code>GetSignalingChannelEndpoint</code> → <code>GetIceServerConfig</code> → <code>ConnectAsMaster</code> 호출을 SDK가 상태 머신으로 감싸 준다는 점이 다른 선택지와 가장 큰 차이다.</p><p>기준은 2026-10 현재 최신 릴리스 <strong>v1.20.0(2026-08-18)</strong>과 기본 브랜치 <code>main</code>이다. 샘플 디렉터리는 <code>samples/common</code>, <code>samples/p2p</code>, <code>samples/webrtcstorage</code>로 나뉘어 있다. 예전 블로그 글에 나오는 <code>samples/Common.c</code> 경로는 지금 <code>samples/common/Common.c</code>다.</p><h2 id="_1-sdk-구조와-의존성" tabindex="-1"><a class="header-anchor" href="#_1-sdk-구조와-의존성"><span>1. SDK 구조와 의존성</span></a></h2><h3 id="저장소와-빌드-결과물" tabindex="-1"><a class="header-anchor" href="#저장소와-빌드-결과물"><span>저장소와 빌드 결과물</span></a></h3><table><thead><tr><th>경로</th><th>내용</th></tr></thead><tbody><tr><td><code>src/include/com/amazonaws/kinesis/video/webrtcclient/Include.h</code></td><td>공개 API 전체. README도 &quot;All Public APIs are documented in our Include.h&quot;라고 적는다</td></tr><tr><td><code>src/source/</code></td><td><code>PeerConnection</code>, <code>Ice</code>, <code>Stun</code>, <code>Sdp</code>, <code>Rtp</code>, <code>Rtcp</code>, <code>Srtp</code>, <code>Sctp</code>, <code>Crypto</code>, <code>Signaling</code>, <code>Metrics</code>, <code>Threadpool</code></td></tr><tr><td><code>samples/common/</code></td><td><code>Common.c</code>(시그널링·세션 관리 공통 로직), <code>GstMedia.c</code>(GStreamer 송출), <code>StaticMedia.c</code>(파일 프레임 송출)</td></tr><tr><td><code>samples/p2p/</code></td><td><code>kvsWebRTCClientMaster.c</code>, <code>kvsWebRTCClientMasterGstSample.c</code>, <code>kvsWebRTCClientViewer.c</code> 등</td></tr><tr><td><code>samples/webrtcstorage/</code></td><td>WebRTC 인제스트(<a href="/study/webrtc/21-kvs-ingestion-storage">21장</a>) 샘플</td></tr><tr><td><code>certs/cert.pem</code></td><td>기본 CA 번들(<code>AWS_KVS_CACERT_PATH</code>로 바꿀 수 있다)</td></tr></tbody></table><p>빌드하면 라이브러리가 두 개 나온다. <code>kvsWebrtcClient</code>는 PeerConnection·ICE·DTLS/SRTP·SCTP·RTP 같은 WebRTC 스택이고, <code>kvsWebrtcSignalingClient</code>는 KVS 시그널링 전용 클라이언트다. 시그널링 클라이언트는 다시 두 AWS 라이브러리에 기댄다. producer-c 저장소의 <code>kvsCommonLws</code>가 자격증명 provider·SigV4 서명·libwebsockets 기반 HTTPS/WSS를 맡고, PIC(Platform Independent Code)의 <code>kvspic</code>이 스레드·타이머·로깅·자료구조를 맡는다. 둘 다 CMake가 함께 내려받아 빌드하며, <code>PRODUCER_C_VERSION_OVERRIDE</code>·<code>PIC_VERSION_OVERRIDE</code>로 git 태그를 고정할 수 있다.</p><p><img src="'+p+'" alt="KVS C SDK 계층 구조. 맨 위 애플리케이션 계층(samples 또는 직접 작성한 앱) 아래에 Include.h 공개 API로 노출되는 kvsWebrtcClient(PeerConnection·ICE·DTLS/SRTP·SCTP·RTP)와 kvsWebrtcSignalingClient(시그널링 상태 머신·WSS·캐시)가 있고, 시그널링 클라이언트는 자격증명·서명을 위해 producer-c의 kvsCommonLws를 쓴다. 그 아래 kvspic과 서드파티 OpenSSL/mbedTLS·libsrtp2·usrsctp·libwebsockets·jsmn이 있다"><img src="'+c+`" alt="KVS C SDK 계층 구조. 맨 위 애플리케이션 계층(samples 또는 직접 작성한 앱) 아래에 Include.h 공개 API로 노출되는 kvsWebrtcClient(PeerConnection·ICE·DTLS/SRTP·SCTP·RTP)와 kvsWebrtcSignalingClient(시그널링 상태 머신·WSS·캐시)가 있고, 시그널링 클라이언트는 자격증명·서명을 위해 producer-c의 kvsCommonLws를 쓴다. 그 아래 kvspic과 서드파티 OpenSSL/mbedTLS·libsrtp2·usrsctp·libwebsockets·jsmn이 있다"></p><h3 id="서드파티-의존성" tabindex="-1"><a class="header-anchor" href="#서드파티-의존성"><span>서드파티 의존성</span></a></h3><p>기본값(<code>-DBUILD_DEPENDENCIES=ON</code>)이면 CMake가 아래 라이브러리를 GitHub에서 받아 소스 빌드하므로 미리 설치할 것이 거의 없다. 배포판 패키지에 링크하려면 README가 요구하는 버전을 맞춰야 한다.</p><table><thead><tr><th>라이브러리</th><th>역할</th><th>시스템 라이브러리에 링크할 때 요구 버전</th></tr></thead><tbody><tr><td>OpenSSL 또는 mbedTLS</td><td>DTLS·TLS·암호 연산</td><td>OpenSSL <code>= 1.1.1x</code> 또는 <code>&gt;= 3.0.0</code> / mbedTLS <code>&gt;= 2.25.0</code>(기본 3.6.x)</td></tr><tr><td>libsrtp2</td><td>SRTP 암복호화</td><td><code>&lt;= 2.5.0</code></td></tr><tr><td>usrsctp</td><td>DataChannel용 SCTP</td><td><code>&lt;= 0.9.5.0</code></td></tr><tr><td>libwebsockets</td><td>시그널링 WSS·HTTPS</td><td><code>&gt;= 4.2.0</code></td></tr><tr><td>jsmn</td><td>JSON 파싱</td><td>(README 의존성 목록에만 있다)</td></tr></tbody></table><p>README의 Key Features는 VP8·H.264·Opus·G.711(A-law/µ-law), DataChannel, NACK, STUN/TURN, IPv4/IPv6, 시그널링 클라이언트 내장, Storage for WebRTC를 꼽는다. 샘플 인자로는 H.265도 받는다(<code>Allowed video-codec: h264 (default), h265</code>). README는 라이브러리 크기를 &quot;Sub 200k&quot;라고 적는다.</p><p>이 SDK의 성격을 한 줄로 요약하면 &quot;인코딩된 프레임을 받아 패킷화·암호화·전송만 하는 스택&quot;이다. README도 &quot;Developer Controlled Media Pipeline — Raw Media for Input/Output&quot;이라고 적는다. libwebrtc처럼 캡처·인코더·혼잡 제어 루프를 다 가진 엔진이 아니라서, 카메라 캡처와 인코딩은 앱이 하고 SDK에는 H.264 access unit을 넘긴다. 디바이스 입장에서는 하드웨어 인코더를 그대로 붙일 수 있다는 장점이 있다. 대신 대역폭 추정 결과를 콜백으로 받아 인코더 비트레이트를 앱이 직접 바꿔야 한다(3절).</p><h3 id="빌드" tabindex="-1"><a class="header-anchor" href="#빌드"><span>빌드</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token function">git</span> clone https://github.com/awslabs/amazon-kinesis-video-streams-webrtc-sdk-c.git <span class="token punctuation">\\</span></span>
<span class="line">  --single-branch <span class="token parameter variable">-b</span> main kvs-webrtc-sdk</span>
<span class="line"></span>
<span class="line"><span class="token comment"># Ubuntu / Raspberry Pi OS: GStreamer 샘플까지 빌드하려면</span></span>
<span class="line"><span class="token function">sudo</span> <span class="token function">apt-get</span> <span class="token function">install</span> cmake m4 pkg-config libssl-dev libcurl4-openssl-dev liblog4cplus-dev <span class="token punctuation">\\</span></span>
<span class="line">  libgstreamer1.0-dev libgstreamer-plugins-base1.0-dev gstreamer1.0-plugins-base-apps <span class="token punctuation">\\</span></span>
<span class="line">  gstreamer1.0-plugins-bad gstreamer1.0-plugins-good gstreamer1.0-plugins-ugly gstreamer1.0-tools</span>
<span class="line"></span>
<span class="line"><span class="token function">mkdir</span> <span class="token parameter variable">-p</span> kvs-webrtc-sdk/build <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> kvs-webrtc-sdk/build</span>
<span class="line">cmake <span class="token punctuation">..</span> <span class="token parameter variable">-DBUILD_DEPENDENCIES</span><span class="token operator">=</span>ON <span class="token parameter variable">-DUSE_OPENSSL</span><span class="token operator">=</span>ON <span class="token parameter variable">-DUSE_OPENSSL3</span><span class="token operator">=</span>ON <span class="token parameter variable">-DPARALLEL_BUILD</span><span class="token operator">=</span>ON</span>
<span class="line"><span class="token function">make</span> <span class="token parameter variable">-j</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">CMake 3.x만 지원한다</p><p>README는 &quot;requires 3.x, CMake 4.x is not yet supported&quot;라고 적는다. 최신 Homebrew나 pip로 깐 CMake가 4.x라면 3.x를 따로 설치해야 한다. GStreamer 샘플은 <code>pkg-config</code>가 GStreamer를 찾을 때만 빌드된다.</p></div><p>자주 만지는 CMake 옵션은 다음과 같다.</p><table><thead><tr><th>옵션</th><th>기본</th><th>의미</th></tr></thead><tbody><tr><td><code>-DBUILD_SAMPLE</code></td><td>ON</td><td>샘플 실행 파일 빌드. 제품 빌드에서는 끈다</td></tr><tr><td><code>-DIOT_CORE_ENABLE_CREDENTIALS</code></td><td>OFF</td><td>샘플이 IoT 인증서 자격증명을 쓰도록 빌드(4절)</td></tr><tr><td><code>-DENABLE_DATA_CHANNEL</code></td><td>ON</td><td>DataChannel 포함</td></tr><tr><td><code>-DBUILD_DEPENDENCIES</code></td><td>ON</td><td>의존 라이브러리를 소스에서 빌드. <code>BUILD_WEBSOCKETS</code>·<code>BUILD_SRTP</code>·<code>BUILD_USRSCTP</code>로 개별 지정 가능</td></tr><tr><td><code>-DUSE_OPENSSL</code> / <code>-DUSE_MBEDTLS</code></td><td>OpenSSL</td><td>암호 백엔드 선택</td></tr><tr><td><code>-DUSE_OPENSSL3</code></td><td>OFF</td><td>OpenSSL 3.x(태그 <code>openssl-3.5.7</code>)로 빌드. v1.20.0부터 지원, 시스템 OpenSSL이 3.0 이상이면 자동 ON</td></tr><tr><td><code>-DBUILD_STATIC_LIBS</code></td><td>OFF</td><td>SDK와 서드파티를 모두 정적 라이브러리로</td></tr><tr><td><code>-DMAX_SDP_SESSION_MEDIA_COUNT</code></td><td>5</td><td>SDP m= 섹션 최대 수. 슬롯 하나당 스택의 <code>SessionDescription</code> 구조체가 약 140 KB 커진다</td></tr><tr><td><code>-DENABLE_KVS_THREADPOOL</code></td><td>OFF</td><td>연결 수립 지연을 줄이는 스레드풀</td></tr><tr><td><code>-DKVS_STACK_SIZE</code></td><td>시스템 기본</td><td><code>THREAD_CREATE()</code>로 만드는 스레드의 스택 크기</td></tr><tr><td><code>-DLINK_PROFILER</code></td><td>OFF</td><td>gperftools 링크(힙·CPU 프로파일)</td></tr><tr><td><code>-DPARALLEL_BUILD</code></td><td>OFF</td><td>의존성을 여러 코어로 빌드</td></tr></tbody></table><p><strong>OpenSSL과 mbedTLS 중 무엇을 고를까.</strong> SDK는 아직 기본값으로 OpenSSL 1.1.1t를 빌드하는데, OpenSSL 1.1.1은 2023년 9월에 지원이 끝났다. README도 새 배포에는 3.x를 권한다. 메모리가 빠듯한 보드라면 mbedTLS가 후보다. 이때 주의할 점은 배포판의 libwebsockets·libsrtp 패키지가 보통 OpenSSL로 빌드돼 있다는 것이다. mbedTLS를 쓰면서 시스템 패키지에 링크하면 링크 오류나 런타임 오류가 날 수 있으니 <code>-DBUILD_DEPENDENCIES=ON</code>으로 같이 소스 빌드하는 편이 안전하다. mbedTLS 경로는 엔트로피를 <code>/dev/urandom</code>에서 얻는데, README는 이게 약한 시스템이면 <code>MBEDTLS_ENTROPY_HARDWARE_ALT</code>로 하드웨어 엔트로피 소스를 연결하라고 &quot;strongly suggested&quot;로 권한다.</p><h2 id="_2-kvswebrtcclientmaster-샘플-흐름" tabindex="-1"><a class="header-anchor" href="#_2-kvswebrtcclientmaster-샘플-흐름"><span>2. kvsWebrtcClientMaster 샘플 흐름</span></a></h2><p>먼저 샘플을 돌려 본다. 빌드 디렉터리에서 채널 이름을 넘기면 된다. 채널이 없으면 샘플이 만든다.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token builtin class-name">cd</span> kvs-webrtc-sdk/build</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_ACCESS_KEY_ID</span><span class="token operator">=</span><span class="token punctuation">..</span>.            <span class="token comment"># 개발용. 제품에서는 4절의 IoT 자격증명</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_SECRET_ACCESS_KEY</span><span class="token operator">=</span><span class="token punctuation">..</span>.</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_DEFAULT_REGION</span><span class="token operator">=</span>ap-northeast-2  <span class="token comment"># 미설정 시 us-west-2</span></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_KVS_LOG_LEVEL</span><span class="token operator">=</span><span class="token number">3</span>                <span class="token comment"># INFO</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># &lt;channelName&gt; &lt;mediaType&gt; &lt;audio-codec&gt; &lt;video-codec&gt;</span></span>
<span class="line">./samples/kvsWebrtcClientMaster tractor-0017 audio-video opus h264</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>mediaType</code>은 <code>audio-video</code>(기본)와 <code>video-only</code>, 비디오 코덱은 <code>h264</code>(기본)와 <code>h265</code>를 받는다. 이 샘플은 카메라 대신 <code>h264SampleFrames/frame-0001.h264</code>부터 1,500장, <code>opusSampleFrames</code>의 오디오 프레임을 반복 송출한다. &quot;Signaling client connection to socket established&quot; 로그가 보이면 KVS 콘솔의 미디어 재생 뷰어나 JS SDK 테스트 페이지에서 같은 채널로 viewer를 붙여 확인한다.</p><p><img src="`+o+'" alt="kvsWebrtcClientMaster 흐름 시퀀스. 디바이스는 ① 자격증명 provider를 만들고 ② createSignalingClientSync·signalingClientFetchSync로 KVS API에 Describe(필요 시 Create)·GetEndpoint·GetIceServerConfig를 호출한 뒤 ③ signalingClientConnectSync로 ConnectAsMaster WSS 연결을 연다. 브라우저가 ConnectAsViewer 후 보낸 SDP_OFFER가 ④ messageReceivedFn으로 들어오면 ⑤ createPeerConnection·addTransceiver·setRemoteDescription·createAnswer를 하고 ⑥ SDP_ANSWER를 보낸다. ⑦ ICE_CANDIDATE를 교환한 뒤 ⑧ ICE·DTLS가 끝나면 writeFrame으로 SRTP 미디어가 P2P 또는 TURN으로 흐른다"><img src="'+i+`" alt="kvsWebrtcClientMaster 흐름 시퀀스. 디바이스는 ① 자격증명 provider를 만들고 ② createSignalingClientSync·signalingClientFetchSync로 KVS API에 Describe(필요 시 Create)·GetEndpoint·GetIceServerConfig를 호출한 뒤 ③ signalingClientConnectSync로 ConnectAsMaster WSS 연결을 연다. 브라우저가 ConnectAsViewer 후 보낸 SDP_OFFER가 ④ messageReceivedFn으로 들어오면 ⑤ createPeerConnection·addTransceiver·setRemoteDescription·createAnswer를 하고 ⑥ SDP_ANSWER를 보낸다. ⑦ ICE_CANDIDATE를 교환한 뒤 ⑧ ICE·DTLS가 끝나면 writeFrame으로 SRTP 미디어가 P2P 또는 TURN으로 흐른다"></p><h3 id="시그널링-클라이언트의-상태-머신" tabindex="-1"><a class="header-anchor" href="#시그널링-클라이언트의-상태-머신"><span>시그널링 클라이언트의 상태 머신</span></a></h3><p><code>createSignalingClientSync</code>로 만든 클라이언트는 <code>Include.h</code>의 <code>SIGNALING_CLIENT_STATE</code> 순서대로 움직인다. 각 상태가 18장의 API 하나에 대응한다.</p><table><thead><tr><th>상태</th><th>하는 일</th></tr></thead><tbody><tr><td><code>NEW</code> → <code>GET_CREDENTIALS</code></td><td>자격증명 provider에서 토큰을 받는다</td></tr><tr><td><code>DESCRIBE</code></td><td><code>DescribeSignalingChannel</code>로 채널 정보 조회</td></tr><tr><td><code>CREATE</code></td><td>채널이 없으면 <code>CreateSignalingChannel</code></td></tr><tr><td><code>GET_ENDPOINT</code></td><td><code>GetSignalingChannelEndpoint</code>로 WSS·HTTPS 엔드포인트 조회</td></tr><tr><td><code>GET_ICE_CONFIG</code></td><td><code>GetIceServerConfig</code>로 TURN 서버·임시 credential 조회</td></tr><tr><td><code>READY</code></td><td>연결 준비 완료(<code>signalingClientFetchSync</code>가 여기까지 진행)</td></tr><tr><td><code>CONNECTING</code> → <code>CONNECTED</code></td><td><code>ConnectAsMaster</code> WSS 연결(<code>signalingClientConnectSync</code>)</td></tr><tr><td><code>DISCONNECTED</code></td><td>연결이 끊김. <code>reconnect</code> 플래그가 켜져 있으면 다시 시도</td></tr></tbody></table><p>인제스트 모드 채널이면 <code>DESCRIBE_MEDIA</code>, <code>JOIN_SESSION</code> 계열 상태가 더 끼어든다(21장).</p><h3 id="핵심-api-호출-골격" tabindex="-1"><a class="header-anchor" href="#핵심-api-호출-골격"><span>핵심 API 호출 골격</span></a></h3><p>아래는 샘플의 <code>Common.c</code>·<code>kvsWebRTCClientMaster.c</code>에서 핵심 호출만 남겨 재구성한 골격이다. 함수 이름과 구조체 필드는 v1.20.0 <code>Include.h</code> 기준이다. 오류 처리는 SDK 관례대로 <code>CHK_STATUS</code> 매크로(실패 시 <code>CleanUp</code> 라벨로 점프)를 쓴다.</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;com/amazonaws/kinesis/video/webrtcclient/Include.h&gt;</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">typedef</span> <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    CHAR peerId<span class="token punctuation">[</span>MAX_SIGNALING_CLIENT_ID_LEN <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">;</span>   <span class="token comment">// viewer의 ClientId</span></span>
<span class="line">    PRtcPeerConnection pc<span class="token punctuation">;</span></span>
<span class="line">    PRtcRtpTransceiver videoTx<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span> ViewerSession<span class="token punctuation">,</span> <span class="token operator">*</span>PViewerSession<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">static</span> SIGNALING_CLIENT_HANDLE gSignaling <span class="token operator">=</span> INVALID_SIGNALING_CLIENT_HANDLE_VALUE<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">static</span> PAwsCredentialProvider gCreds <span class="token operator">=</span> <span class="token constant">NULL</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">static</span> PCHAR gRegion <span class="token operator">=</span> <span class="token string">&quot;ap-northeast-2&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* 1~3) 자격증명 → 시그널링 클라이언트 생성 → fetch → connect */</span></span>
<span class="line">STATUS <span class="token function">startMaster</span><span class="token punctuation">(</span>PCHAR channelName<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    STATUS retStatus <span class="token operator">=</span> STATUS_SUCCESS<span class="token punctuation">;</span></span>
<span class="line">    ChannelInfo channelInfo<span class="token punctuation">;</span></span>
<span class="line">    SignalingClientInfo clientInfo<span class="token punctuation">;</span></span>
<span class="line">    SignalingClientCallbacks callbacks<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">initKvsWebRtc</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>                     <span class="token comment">// 프로세스당 한 번</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// IoT 인증서로 임시 자격증명을 받는 provider (4절). 개발 중엔 createStaticCredentialProvider</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">createLwsIotCredentialProvider</span><span class="token punctuation">(</span></span>
<span class="line">        <span class="token function">getenv</span><span class="token punctuation">(</span><span class="token string">&quot;AWS_IOT_CORE_CREDENTIAL_ENDPOINT&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">getenv</span><span class="token punctuation">(</span><span class="token string">&quot;AWS_IOT_CORE_CERT&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">getenv</span><span class="token punctuation">(</span><span class="token string">&quot;AWS_IOT_CORE_PRIVATE_KEY&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&quot;/etc/kvs/cert.pem&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token function">getenv</span><span class="token punctuation">(</span><span class="token string">&quot;AWS_IOT_CORE_ROLE_ALIAS&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span> channelName <span class="token comment">/* thing 이름 = 채널 이름 */</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>gCreds<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>channelInfo<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>channelInfo<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>version <span class="token operator">=</span> CHANNEL_INFO_CURRENT_VERSION<span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>pChannelName <span class="token operator">=</span> channelName<span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>pRegion <span class="token operator">=</span> gRegion<span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>channelType <span class="token operator">=</span> SIGNALING_CHANNEL_TYPE_SINGLE_MASTER<span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>channelRoleType <span class="token operator">=</span> SIGNALING_CHANNEL_ROLE_TYPE_MASTER<span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>cachingPolicy <span class="token operator">=</span> SIGNALING_API_CALL_CACHE_TYPE_FILE<span class="token punctuation">;</span>   <span class="token comment">// Describe·GetEndpoint 결과를 파일에 캐시</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>cachingPeriod <span class="token operator">=</span> SIGNALING_API_CALL_CACHE_TTL_SENTINEL_VALUE<span class="token punctuation">;</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>retry <span class="token operator">=</span> TRUE<span class="token punctuation">;</span>                        <span class="token comment">// 네트워크 호출 재시도</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>reconnect <span class="token operator">=</span> TRUE<span class="token punctuation">;</span>                    <span class="token comment">// 연결이 끊기면 재연결 시도</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>messageTtl <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>                      <span class="token comment">// 0 = 기본 60초</span></span>
<span class="line">    channelInfo<span class="token punctuation">.</span>pCertPath <span class="token operator">=</span> <span class="token string">&quot;/etc/kvs/cert.pem&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>clientInfo<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>clientInfo<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    clientInfo<span class="token punctuation">.</span>version <span class="token operator">=</span> SIGNALING_CLIENT_INFO_CURRENT_VERSION<span class="token punctuation">;</span></span>
<span class="line">    clientInfo<span class="token punctuation">.</span>loggingLevel <span class="token operator">=</span> LOG_LEVEL_WARN<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">STRCPY</span><span class="token punctuation">(</span>clientInfo<span class="token punctuation">.</span>clientId<span class="token punctuation">,</span> <span class="token string">&quot;ProducerMaster&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 샘플의 SAMPLE_MASTER_CLIENT_ID</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>callbacks<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>callbacks<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    callbacks<span class="token punctuation">.</span>version <span class="token operator">=</span> SIGNALING_CLIENT_CALLBACKS_CURRENT_VERSION<span class="token punctuation">;</span></span>
<span class="line">    callbacks<span class="token punctuation">.</span>messageReceivedFn <span class="token operator">=</span> onSignalingMessage<span class="token punctuation">;</span>   <span class="token comment">// SDP_OFFER, ICE_CANDIDATE 수신</span></span>
<span class="line">    callbacks<span class="token punctuation">.</span>errorReportFn <span class="token operator">=</span> onSignalingError<span class="token punctuation">;</span></span>
<span class="line">    callbacks<span class="token punctuation">.</span>stateChangeFn <span class="token operator">=</span> onSignalingState<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">createSignalingClientSync</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>clientInfo<span class="token punctuation">,</span> <span class="token operator">&amp;</span>channelInfo<span class="token punctuation">,</span> <span class="token operator">&amp;</span>callbacks<span class="token punctuation">,</span> gCreds<span class="token punctuation">,</span> <span class="token operator">&amp;</span>gSignaling<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">signalingClientFetchSync</span><span class="token punctuation">(</span>gSignaling<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// Describe(→Create)·GetEndpoint·GetIceServerConfig</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">signalingClientConnectSync</span><span class="token punctuation">(</span>gSignaling<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// ConnectAsMaster</span></span>
<span class="line"></span>
<span class="line">CleanUp<span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">return</span> retStatus<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* 5) viewer마다 PeerConnection 하나 */</span></span>
<span class="line">STATUS <span class="token function">createViewerSession</span><span class="token punctuation">(</span>PCHAR peerId<span class="token punctuation">,</span> PViewerSession s<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    STATUS retStatus <span class="token operator">=</span> STATUS_SUCCESS<span class="token punctuation">;</span></span>
<span class="line">    RtcConfiguration cfg<span class="token punctuation">;</span></span>
<span class="line">    RtcMediaStreamTrack video<span class="token punctuation">;</span></span>
<span class="line">    RtcRtpTransceiverInit init<span class="token punctuation">;</span></span>
<span class="line">    PIceConfigInfo pIce<span class="token punctuation">;</span></span>
<span class="line">    UINT32 iceCount<span class="token punctuation">,</span> j<span class="token punctuation">,</span> k <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">STRNCPY</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>peerId<span class="token punctuation">,</span> peerId<span class="token punctuation">,</span> MAX_SIGNALING_CLIENT_ID_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>cfg<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>cfg<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">SNPRINTF</span><span class="token punctuation">(</span>cfg<span class="token punctuation">.</span>iceServers<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>urls<span class="token punctuation">,</span> MAX_ICE_CONFIG_URI_LEN<span class="token punctuation">,</span> KINESIS_VIDEO_STUN_URL<span class="token punctuation">,</span></span>
<span class="line">             gRegion<span class="token punctuation">,</span> KINESIS_VIDEO_STUN_URL_POSTFIX<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// stun:stun.kinesisvideo.&lt;region&gt;.amazonaws.com:443</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// TURN: fetch 단계에서 받아 둔 GetIceServerConfig 결과(credential TTL 300초)</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">signalingClientGetIceConfigInfoCount</span><span class="token punctuation">(</span>gSignaling<span class="token punctuation">,</span> <span class="token operator">&amp;</span>iceCount<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>iceCount <span class="token operator">&gt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">signalingClientGetIceConfigInfo</span><span class="token punctuation">(</span>gSignaling<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>pIce<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 샘플도 수집 시간을 줄이려고 하나만 쓴다</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span>j <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> j <span class="token operator">&lt;</span> pIce<span class="token operator">-&gt;</span>uriCount<span class="token punctuation">;</span> j<span class="token operator">++</span><span class="token punctuation">,</span> k<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">STRNCPY</span><span class="token punctuation">(</span>cfg<span class="token punctuation">.</span>iceServers<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>urls<span class="token punctuation">,</span> pIce<span class="token operator">-&gt;</span>uris<span class="token punctuation">[</span>j<span class="token punctuation">]</span><span class="token punctuation">,</span> MAX_ICE_CONFIG_URI_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">STRNCPY</span><span class="token punctuation">(</span>cfg<span class="token punctuation">.</span>iceServers<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>username<span class="token punctuation">,</span> pIce<span class="token operator">-&gt;</span>userName<span class="token punctuation">,</span> MAX_ICE_CONFIG_USER_NAME_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">STRNCPY</span><span class="token punctuation">(</span>cfg<span class="token punctuation">.</span>iceServers<span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token punctuation">.</span>credential<span class="token punctuation">,</span> pIce<span class="token operator">-&gt;</span>password<span class="token punctuation">,</span> MAX_ICE_CONFIG_CREDENTIAL_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">createPeerConnection</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>cfg<span class="token punctuation">,</span> <span class="token operator">&amp;</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">peerConnectionOnIceCandidate</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> <span class="token punctuation">(</span>UINT64<span class="token punctuation">)</span> s<span class="token punctuation">,</span> onLocalCandidate<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">peerConnectionOnConnectionStateChange</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> <span class="token punctuation">(</span>UINT64<span class="token punctuation">)</span> s<span class="token punctuation">,</span> onPcStateChange<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">addSupportedCodec</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> RTC_CODEC_H264_PROFILE_42E01F_LEVEL_ASYMMETRY_ALLOWED_PACKETIZATION_MODE<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>video<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>video<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    video<span class="token punctuation">.</span>kind <span class="token operator">=</span> MEDIA_STREAM_TRACK_KIND_VIDEO<span class="token punctuation">;</span></span>
<span class="line">    video<span class="token punctuation">.</span>codec <span class="token operator">=</span> RTC_CODEC_H264_PROFILE_42E01F_LEVEL_ASYMMETRY_ALLOWED_PACKETIZATION_MODE<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">STRCPY</span><span class="token punctuation">(</span>video<span class="token punctuation">.</span>streamId<span class="token punctuation">,</span> <span class="token string">&quot;tractor-0017&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">STRCPY</span><span class="token punctuation">(</span>video<span class="token punctuation">.</span>trackId<span class="token punctuation">,</span> <span class="token string">&quot;front-cam&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>init<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>init<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    init<span class="token punctuation">.</span>direction <span class="token operator">=</span> RTC_RTP_TRANSCEIVER_DIRECTION_SENDONLY<span class="token punctuation">;</span>   <span class="token comment">// 샘플은 SENDRECV</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">addTransceiver</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> <span class="token operator">&amp;</span>video<span class="token punctuation">,</span> <span class="token operator">&amp;</span>init<span class="token punctuation">,</span> <span class="token operator">&amp;</span>s<span class="token operator">-&gt;</span>videoTx<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">CleanUp<span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">return</span> retStatus<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* 4~6) 오퍼 처리 → 앤서 전송 */</span></span>
<span class="line">STATUS <span class="token function">answerOffer</span><span class="token punctuation">(</span>PViewerSession s<span class="token punctuation">,</span> PSignalingMessage pOffer<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    STATUS retStatus <span class="token operator">=</span> STATUS_SUCCESS<span class="token punctuation">;</span></span>
<span class="line">    RtcSessionDescriptionInit offer<span class="token punctuation">,</span> answer<span class="token punctuation">;</span></span>
<span class="line">    SignalingMessage msg<span class="token punctuation">;</span></span>
<span class="line">    UINT32 len <span class="token operator">=</span> MAX_SIGNALING_MESSAGE_LEN<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>offer<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>offer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>answer<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>answer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>msg<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">deserializeSessionDescriptionInit</span><span class="token punctuation">(</span>pOffer<span class="token operator">-&gt;</span>payload<span class="token punctuation">,</span> pOffer<span class="token operator">-&gt;</span>payloadLen<span class="token punctuation">,</span> <span class="token operator">&amp;</span>offer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">setRemoteDescription</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> <span class="token operator">&amp;</span>offer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">setLocalDescription</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> <span class="token operator">&amp;</span>answer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 샘플 순서: 빈 init으로 먼저 호출해 ICE 수집 시작</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">createAnswer</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> <span class="token operator">&amp;</span>answer<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// 원격이 Trickle ICE를 지원할 때만 바로 앤서</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">serializeSessionDescriptionInit</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>answer<span class="token punctuation">,</span> msg<span class="token punctuation">.</span>payload<span class="token punctuation">,</span> <span class="token operator">&amp;</span>len<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    msg<span class="token punctuation">.</span>version <span class="token operator">=</span> SIGNALING_MESSAGE_CURRENT_VERSION<span class="token punctuation">;</span></span>
<span class="line">    msg<span class="token punctuation">.</span>messageType <span class="token operator">=</span> SIGNALING_MESSAGE_TYPE_ANSWER<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">STRNCPY</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span>peerClientId<span class="token punctuation">,</span> s<span class="token operator">-&gt;</span>peerId<span class="token punctuation">,</span> MAX_SIGNALING_CLIENT_ID_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// master는 수신자 지정이 필수</span></span>
<span class="line">    msg<span class="token punctuation">.</span>payloadLen <span class="token operator">=</span> <span class="token punctuation">(</span>UINT32<span class="token punctuation">)</span> <span class="token function">STRLEN</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span>payload<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">signalingClientSendMessageSync</span><span class="token punctuation">(</span>gSignaling<span class="token punctuation">,</span> <span class="token operator">&amp;</span>msg<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">CleanUp<span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">return</span> retStatus<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* 로컬 후보 → ICE_CANDIDATE 메시지 (candidateJson == NULL이면 수집 완료) */</span></span>
<span class="line">VOID <span class="token function">onLocalCandidate</span><span class="token punctuation">(</span>UINT64 customData<span class="token punctuation">,</span> PCHAR candidateJson<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    PViewerSession s <span class="token operator">=</span> <span class="token punctuation">(</span>PViewerSession<span class="token punctuation">)</span> customData<span class="token punctuation">;</span></span>
<span class="line">    SignalingMessage msg<span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>candidateJson <span class="token operator">==</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>msg<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>msg<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    msg<span class="token punctuation">.</span>version <span class="token operator">=</span> SIGNALING_MESSAGE_CURRENT_VERSION<span class="token punctuation">;</span></span>
<span class="line">    msg<span class="token punctuation">.</span>messageType <span class="token operator">=</span> SIGNALING_MESSAGE_TYPE_ICE_CANDIDATE<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">STRNCPY</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span>peerClientId<span class="token punctuation">,</span> s<span class="token operator">-&gt;</span>peerId<span class="token punctuation">,</span> MAX_SIGNALING_CLIENT_ID_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    msg<span class="token punctuation">.</span>payloadLen <span class="token operator">=</span> <span class="token punctuation">(</span>UINT32<span class="token punctuation">)</span> <span class="token function">STRNLEN</span><span class="token punctuation">(</span>candidateJson<span class="token punctuation">,</span> MAX_SIGNALING_MESSAGE_LEN<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">STRNCPY</span><span class="token punctuation">(</span>msg<span class="token punctuation">.</span>payload<span class="token punctuation">,</span> candidateJson<span class="token punctuation">,</span> msg<span class="token punctuation">.</span>payloadLen<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">signalingClientSendMessageSync</span><span class="token punctuation">(</span>gSignaling<span class="token punctuation">,</span> <span class="token operator">&amp;</span>msg<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 실제 샘플은 전송 뮤텍스로 직렬화한다</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* 시그널링 수신 콜백 */</span></span>
<span class="line">STATUS <span class="token function">onSignalingMessage</span><span class="token punctuation">(</span>UINT64 customData<span class="token punctuation">,</span> PReceivedSignalingMessage pRecv<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    STATUS retStatus <span class="token operator">=</span> STATUS_SUCCESS<span class="token punctuation">;</span></span>
<span class="line">    PSignalingMessage m <span class="token operator">=</span> <span class="token operator">&amp;</span>pRecv<span class="token operator">-&gt;</span>signalingMessage<span class="token punctuation">;</span></span>
<span class="line">    PViewerSession s <span class="token operator">=</span> <span class="token function">findSession</span><span class="token punctuation">(</span>m<span class="token operator">-&gt;</span>peerClientId<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// ClientId 해시 → 세션</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">switch</span> <span class="token punctuation">(</span>m<span class="token operator">-&gt;</span>messageType<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">case</span> SIGNALING_MESSAGE_TYPE_OFFER<span class="token operator">:</span></span>
<span class="line">            <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">allocSession</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>s<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">createViewerSession</span><span class="token punctuation">(</span>m<span class="token operator">-&gt;</span>peerClientId<span class="token punctuation">,</span> s<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">answerOffer</span><span class="token punctuation">(</span>s<span class="token punctuation">,</span> m<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">case</span> SIGNALING_MESSAGE_TYPE_ICE_CANDIDATE<span class="token operator">:</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>s <span class="token operator">!=</span> <span class="token constant">NULL</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>                              <span class="token comment">// 샘플은 오퍼보다 먼저 온 후보를 큐에 보관한다</span></span>
<span class="line">                RtcIceCandidateInit cand<span class="token punctuation">;</span></span>
<span class="line">                <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">deserializeRtcIceCandidateInit</span><span class="token punctuation">(</span>m<span class="token operator">-&gt;</span>payload<span class="token punctuation">,</span> m<span class="token operator">-&gt;</span>payloadLen<span class="token punctuation">,</span> <span class="token operator">&amp;</span>cand<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token function">CHK_STATUS</span><span class="token punctuation">(</span><span class="token function">addIceCandidate</span><span class="token punctuation">(</span>s<span class="token operator">-&gt;</span>pc<span class="token punctuation">,</span> cand<span class="token punctuation">.</span>candidate<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">default</span><span class="token operator">:</span></span>
<span class="line">            <span class="token keyword">break</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">CleanUp<span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">return</span> retStatus<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>연결이 끝나면 미디어 스레드가 프레임마다 모든 세션에 <code>writeFrame</code>을 호출한다. 이 부분은 3절의 GStreamer 콜백에서 같이 본다. 종료할 때는 <code>closePeerConnection</code> → <code>freePeerConnection</code> → <code>freeSignalingClient</code> → <code>freeIotCredentialProvider</code> → <code>deinitKvsWebRtc</code> 순서로 정리한다.</p><h3 id="샘플-코드에서-읽어-둘-동작" tabindex="-1"><a class="header-anchor" href="#샘플-코드에서-읽어-둘-동작"><span>샘플 코드에서 읽어 둘 동작</span></a></h3><p><strong>API 순서가 브라우저와 다르다.</strong> 브라우저는 <code>createAnswer</code> → <code>setLocalDescription</code> 순서지만, 샘플의 <code>handleOffer</code>는 빈 <code>RtcSessionDescriptionInit</code>으로 <code>setLocalDescription</code>을 먼저 불러 ICE 수집을 시작하고 그다음 <code>createAnswer</code>로 SDP를 채운다. 원격이 Trickle ICE를 지원하지 않으면(<code>canTrickleIceCandidates</code>가 FALSE) 앤서를 바로 보내지 않고, <code>onIceCandidate</code>에 NULL이 와서 수집이 끝났을 때 보낸다. 브라우저 viewer는 Trickle ICE를 쓰므로 보통은 바로 보낸다.</p><p><strong>viewer마다 PeerConnection이 하나씩 생긴다.</strong> 샘플은 viewer의 ClientId를 CRC32 해시해 세션을 찾는 해시 테이블과 세션 배열을 둔다. 배열 크기 <code>DEFAULT_MAX_CONCURRENT_STREAMING_SESSION</code>은 10으로, KVS 채널의 기본 viewer 한도 10과 같다. 한도를 넘으면 &quot;Max simultaneous streaming session count reached.&quot; 로그를 남기고 오퍼를 버린다. viewer 한도(<code>ConnectAsViewer connections per signaling channel</code>)는 Service Quotas에서 올릴 수 있지만, 그때는 디바이스 쪽 배열도 같이 키워야 한다. 같은 ClientId로 오퍼가 다시 오면 기존 세션이 살아 있을 때는 같은 PeerConnection으로 재협상하고, 이미 끊긴 세션이면 버리고 새로 만든다.</p><p><strong>업링크가 viewer 수만큼 곱해진다.</strong> <a href="/study/webrtc/16-aws-landscape">16장</a>에서 강조했듯 KVS 기본 모드는 SFU가 아니다. 운영자 4명이 같은 트랙터를 보면 디바이스는 같은 프레임을 4번 패킷화·SRTP 암호화해 4개 경로로 보낸다. 1.5 Mbps 스트림이면 LTE 업링크로 6 Mbps가 필요하다. 업링크 예산이 작은 농기계라면 동시 viewer 상한을 제품 정책으로 정하거나(백엔드에서 viewer 세션 발급을 제한, <a href="/study/webrtc/20-kvs-viewer-backend">20장</a>) 21장의 인제스트 모드를 검토한다.</p><p><strong>시그널링 연결은 오래 유지되지 않는다.</strong> KVS는 <code>ConnectAsMaster</code> 연결을 최대 1시간(3,600초), idle 10분(600초)으로 제한하고, <code>GO_AWAY</code> 뒤 유예는 60초다. 셋 다 조정할 수 없는 hard 한도다. <code>channelInfo.reconnect = TRUE</code>면 SDK가 끊긴 연결을 다시 맺으려 시도하고, 샘플은 여기에 더해 5초마다 깨는 감시 루프(<code>sessionCleanupWait</code>)를 돈다. 이 루프는 <code>STATUS_SIGNALING_ICE_CONFIG_REFRESH_FAILED</code>나 <code>STATUS_SIGNALING_RECONNECT_FAILED</code> 오류가 오면 시그널링 클라이언트를 새로 만들고, 상태가 <code>READY</code>에 머물러 있으면 <code>signalingClientConnectSync</code>를 다시 부른다. 24시간 켜져 있는 농기계라면 이 감시 루프를 그대로 가져가야 한다. 참고로 <code>GetIceServerConfig</code>의 <code>SessionExpiredException</code> 설명에는 &quot;session is valid for 45 minutes&quot;라는 별도 수치가 있어 1시간 한도와 숫자가 다르다. 둘의 관계는 문서에 설명이 없으니 재연결 로직은 어느 쪽이든 견디게 짠다.</p><p><strong>캐시가 재부팅 폭주를 막는다.</strong> 샘플은 <code>cachingPolicy = SIGNALING_API_CALL_CACHE_TYPE_FILE_EXCEPT_DESCRIBE_MEDIA</code>를 쓴다. <code>DescribeSignalingChannel</code>·<code>GetSignalingChannelEndpoint</code> 결과를 파일에 남겨 재시작해도 다시 부르지 않는다. 이 두 API는 채널당 5 TPS 한도라서, 전원이 불안정해 재부팅을 반복하는 디바이스가 있으면 캐시가 없을 때 스로틀(<code>ClientLimitExceededException</code>)에 걸리기 쉽다.</p><p><strong>DTLS 인증서 생성이 느리다.</strong> README에 따르면 저사양 임베디드에서 <code>createCertificateAndKey</code>가 5~15초 걸릴 수 있고, 오퍼를 받을 때마다 호출된다. 샘플은 타이머로 인증서를 미리 만들어 큐에 쌓아 두고(<code>KVS_PRE_GENERATE_CERT_ENABLED</code> 기본 TRUE, 주기 3초, 최대 2개) PeerConnection을 만들 때 하나씩 꺼내 쓴다. README는 인증서를 연결마다 바꾸라고 권한다(<a href="/study/webrtc/10-dtls-srtp">10장</a>의 <code>a=fingerprint</code> 검증과 연결된다).</p><h3 id="viewer-샘플은-언제-쓰나" tabindex="-1"><a class="header-anchor" href="#viewer-샘플은-언제-쓰나"><span>viewer 샘플은 언제 쓰나</span></a></h3><p><code>kvsWebrtcClientViewer &lt;channelName&gt; &lt;audio-codec&gt; &lt;video-codec&gt;</code>는 같은 SDK로 viewer 역할을 한다. ClientId를 <code>ConsumerViewer_&lt;난수&gt;</code>로 만들고, 세션을 만든 뒤 <code>setLocalDescription</code> → <code>createOffer</code> → <code>signalingClientSendMessageSync</code>(OFFER)로 오퍼를 보낸다. 받은 프레임은 <code>transceiverOnFrame</code> 콜백으로 들어오며 샘플은 크기만 로그로 찍는다. <code>kvsWebrtcClientViewerGstSample</code>은 받은 미디어를 <code>filesink</code>로 저장하는데, README는 <code>matroskamux</code>가 중간에 캡스가 바뀌면 처리하지 못하는 문제를 Known issue로 적는다.</p><p>현장에서는 쓸모가 꽤 있다. 브라우저 없이 master를 검증하는 CI 통합 테스트, 농장 사무실 엣지 게이트웨이가 여러 농기계 영상을 받아 로컬 녹화하는 구성, 디바이스 간 영상 전달이 그런 경우다.</p><h2 id="_3-gstreamer-샘플과-하드웨어-인코더-연동" tabindex="-1"><a class="header-anchor" href="#_3-gstreamer-샘플과-하드웨어-인코더-연동"><span>3. GStreamer 샘플과 하드웨어 인코더 연동</span></a></h2><p><code>kvsWebrtcClientMasterGstSample</code>은 송출 소스를 GStreamer 파이프라인으로 바꾼 샘플이다.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token comment"># &lt;channelName&gt; &lt;mediaType&gt; &lt;sourceType&gt;</span></span>
<span class="line">./samples/kvsWebrtcClientMasterGstSample tractor-0017 video-only devicesrc</span>
<span class="line">./samples/kvsWebrtcClientMasterGstSample tractor-0017 audio-video testsrc opus h264</span>
<span class="line">./samples/kvsWebrtcClientMasterGstSample tractor-0017 video-only rtspsrc rtsp://192.168.0.64/stream1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>sourceType</code>은 <code>testsrc</code>(videotestsrc), <code>devicesrc</code>(<code>autovideosrc</code>·<code>autoaudiosrc</code>, 기본), <code>rtspsrc</code>(IP 카메라) 중 하나다. viewer가 보낸 오디오는 <code>autoaudiosink</code>로 재생한다.</p><h3 id="appsink-→-writeframe-구조" tabindex="-1"><a class="header-anchor" href="#appsink-→-writeframe-구조"><span>appsink → writeFrame 구조</span></a></h3><p>샘플의 <code>GstMedia.c</code>가 하는 일은 단순하다. 파이프라인 끝을 <code>appsink name=appsink-video emit-signals=TRUE</code>로 두고, <code>&quot;new-sample&quot;</code> 시그널에 콜백을 건다. 콜백은 버퍼를 꺼내 <code>Frame</code> 구조체에 담고, 연결된 모든 세션에 <code>writeFrame</code>을 호출한다.</p><p><img src="`+l+'" alt="GStreamer appsink에서 writeFrame으로 이어지는 구조. 위쪽 GStreamer 파이프라인은 v4l2src(카메라) → v4l2convert → HW 인코더(v4l2h264enc 등) → h264parse config-interval=-1 → appsink 순서이고 caps는 byte-stream·alignment=au·profile=baseline이다. appsink의 new-sample 시그널이 on_new_sample() 콜백을 부르고, 콜백은 세션 1·2·…·N(각각 PeerConnection)에 writeFrame을 N번 호출해 패킷화·SRTP 암호화·송신한다. 각 세션의 TWCC 추정은 점선으로 하나뿐인 인코더의 bitrate로 되돌아가 N개 세션이 인코더 하나를 공유한다"><img src="'+r+`" alt="GStreamer appsink에서 writeFrame으로 이어지는 구조. 위쪽 GStreamer 파이프라인은 v4l2src(카메라) → v4l2convert → HW 인코더(v4l2h264enc 등) → h264parse config-interval=-1 → appsink 순서이고 caps는 byte-stream·alignment=au·profile=baseline이다. appsink의 new-sample 시그널이 on_new_sample() 콜백을 부르고, 콜백은 세션 1·2·…·N(각각 PeerConnection)에 writeFrame을 N번 호출해 패킷화·SRTP 암호화·송신한다. 각 세션의 TWCC 추정은 점선으로 하나뿐인 인코더의 bitrate로 되돌아가 N개 세션이 인코더 하나를 공유한다"></p><p>샘플 콜백을 실제 카메라에 맞게 다듬으면 다음과 같다.</p><div class="language-c line-numbers-mode" data-highlighter="prismjs" data-ext="c" data-title="c"><pre><code><span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;gst/gst.h&gt;</span></span></span>
<span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;gst/app/gstappsink.h&gt;</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">static</span> ViewerSession<span class="token operator">*</span> gSessions<span class="token punctuation">[</span><span class="token number">10</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">static</span> UINT32 gSessionCount <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">static</span> MUTEX gSessionsLock<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">static</span> VOID <span class="token function">sendVideoFrame</span><span class="token punctuation">(</span>PBYTE data<span class="token punctuation">,</span> UINT32 size<span class="token punctuation">,</span> UINT64 pts100ns<span class="token punctuation">,</span> BOOL key<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    Frame f<span class="token punctuation">;</span></span>
<span class="line">    UINT32 i<span class="token punctuation">;</span></span>
<span class="line">    <span class="token function">MEMSET</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>f<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token function">SIZEOF</span><span class="token punctuation">(</span>f<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    f<span class="token punctuation">.</span>version <span class="token operator">=</span> FRAME_CURRENT_VERSION<span class="token punctuation">;</span></span>
<span class="line">    f<span class="token punctuation">.</span>trackId <span class="token operator">=</span> DEFAULT_VIDEO_TRACK_ID<span class="token punctuation">;</span></span>
<span class="line">    f<span class="token punctuation">.</span>frameData <span class="token operator">=</span> data<span class="token punctuation">;</span></span>
<span class="line">    f<span class="token punctuation">.</span>size <span class="token operator">=</span> size<span class="token punctuation">;</span></span>
<span class="line">    f<span class="token punctuation">.</span>presentationTs <span class="token operator">=</span> f<span class="token punctuation">.</span>decodingTs <span class="token operator">=</span> pts100ns<span class="token punctuation">;</span>          <span class="token comment">// SDK 시간 단위는 100 ns</span></span>
<span class="line">    f<span class="token punctuation">.</span>flags <span class="token operator">=</span> key <span class="token operator">?</span> FRAME_FLAG_KEY_FRAME <span class="token operator">:</span> FRAME_FLAG_NONE<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token function">MUTEX_LOCK</span><span class="token punctuation">(</span>gSessionsLock<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span>i <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> i <span class="token operator">&lt;</span> gSessionCount<span class="token punctuation">;</span> i<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        STATUS st <span class="token operator">=</span> <span class="token function">writeFrame</span><span class="token punctuation">(</span>gSessions<span class="token punctuation">[</span>i<span class="token punctuation">]</span><span class="token operator">-&gt;</span>videoTx<span class="token punctuation">,</span> <span class="token operator">&amp;</span>f<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 세션마다 패킷화 + SRTP</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>st <span class="token operator">==</span> STATUS_SRTP_NOT_READY_YET<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// DTLS가 아직 안 끝났다. 버리고, 이 세션이 준비되면 키프레임부터 보내야 한다</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token function">MUTEX_UNLOCK</span><span class="token punctuation">(</span>gSessionsLock<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">static</span> GstFlowReturn <span class="token function">onNewVideoSample</span><span class="token punctuation">(</span>GstElement<span class="token operator">*</span> sink<span class="token punctuation">,</span> gpointer user<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    GstSample<span class="token operator">*</span> sample <span class="token operator">=</span> <span class="token function">gst_app_sink_pull_sample</span><span class="token punctuation">(</span><span class="token function">GST_APP_SINK</span><span class="token punctuation">(</span>sink<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    GstBuffer<span class="token operator">*</span> buf <span class="token operator">=</span> <span class="token function">gst_sample_get_buffer</span><span class="token punctuation">(</span>sample<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    GstMapInfo map<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">GST_BUFFER_PTS_IS_VALID</span><span class="token punctuation">(</span>buf<span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token function">gst_buffer_map</span><span class="token punctuation">(</span>buf<span class="token punctuation">,</span> <span class="token operator">&amp;</span>map<span class="token punctuation">,</span> GST_MAP_READ<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        GstSegment<span class="token operator">*</span> seg <span class="token operator">=</span> <span class="token function">gst_sample_get_segment</span><span class="token punctuation">(</span>sample<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        GstClockTime rt <span class="token operator">=</span> <span class="token function">gst_segment_to_running_time</span><span class="token punctuation">(</span>seg<span class="token punctuation">,</span> GST_FORMAT_TIME<span class="token punctuation">,</span> <span class="token function">GST_BUFFER_PTS</span><span class="token punctuation">(</span>buf<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        BOOL key <span class="token operator">=</span> <span class="token operator">!</span><span class="token function">GST_BUFFER_FLAG_IS_SET</span><span class="token punctuation">(</span>buf<span class="token punctuation">,</span> GST_BUFFER_FLAG_DELTA_UNIT<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">sendVideoFrame</span><span class="token punctuation">(</span>map<span class="token punctuation">.</span>data<span class="token punctuation">,</span> <span class="token punctuation">(</span>UINT32<span class="token punctuation">)</span> map<span class="token punctuation">.</span>size<span class="token punctuation">,</span> rt <span class="token operator">/</span> <span class="token number">100</span> <span class="token comment">/* ns → 100 ns */</span><span class="token punctuation">,</span> key<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token function">gst_buffer_unmap</span><span class="token punctuation">(</span>buf<span class="token punctuation">,</span> <span class="token operator">&amp;</span>map<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    <span class="token function">gst_sample_unref</span><span class="token punctuation">(</span>sample<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token keyword">return</span> GST_FLOW_OK<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* 파이프라인 연결 */</span></span>
<span class="line"><span class="token comment">// GstElement* appsink = gst_bin_get_by_name(GST_BIN(pipeline), &quot;appsink-video&quot;);</span></span>
<span class="line"><span class="token comment">// g_signal_connect(appsink, &quot;new-sample&quot;, G_CALLBACK(onNewVideoSample), NULL);</span></span>
<span class="line"><span class="token comment">// gst_element_set_state(pipeline, GST_STATE_PLAYING);</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>appsink</code> 앞 캡스는 세 가지를 맞춘다. <code>stream-format=byte-stream</code>은 Annex-B 시작 코드가 붙은 형식이다. SDK가 이 시작 코드로 NAL 단위를 잘라 RTP로 패킷화한다(<a href="/study/webrtc/08-rtp-codecs">08장</a>의 FU-A). <code>alignment=au</code>는 버퍼 하나가 access unit(프레임) 하나라는 뜻이다. <code>profile=baseline</code>은 SDK가 SDP에 광고하는 <code>RTC_CODEC_H264_PROFILE_42E01F_LEVEL_ASYMMETRY_ALLOWED_PACKETIZATION_MODE</code>(profile-level-id <code>42e01f</code>, Constrained Baseline)와 맞추기 위해서다. B-프레임은 끈다. 샘플의 x264enc 설정도 <code>bframes=0 tune=zerolatency</code>다. <code>h264parse config-interval=-1</code>은 키프레임마다 SPS/PPS를 다시 넣어, 중간에 붙은 viewer도 첫 키프레임부터 디코딩할 수 있게 한다. README는 H.265에서는 이 설정이 없으면 첫 키프레임 뒤에 화면이 멈춘다고 적는다.</p><h3 id="하드웨어-인코더-파이프라인" tabindex="-1"><a class="header-anchor" href="#하드웨어-인코더-파이프라인"><span>하드웨어 인코더 파이프라인</span></a></h3><p>샘플 소스(<code>GstMedia.c</code>)의 주석에 Raspberry Pi 하드웨어 인코더 예시가 들어 있다.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">v4l2src device=/dev/video0 ! queue ! v4l2convert !</span>
<span class="line">video/x-raw,format=I420,width=640,height=480,framerate=30/1 !</span>
<span class="line">v4l2h264enc ! h264parse !</span>
<span class="line">video/x-h264,stream-format=byte-stream,alignment=au,width=640,height=480,framerate=30/1,profile=baseline,level=(string)4 !</span>
<span class="line">appsink sync=TRUE emit-signals=TRUE name=appsink-video</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Jetson 계열은 NVENC를 쓰는 <code>nvv4l2h264enc</code>로 바꾼다. 아래 속성 이름은 JetPack 버전마다 다를 수 있으니 보드에서 <code>gst-inspect-1.0 nvv4l2h264enc</code>로 확인한다.</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">nvarguscamerasrc ! video/x-raw(memory:NVMM),width=1280,height=720,framerate=30/1 !</span>
<span class="line">nvv4l2h264enc name=sampleVideoEncoder insert-sps-pps=true idrinterval=30 bitrate=2000000 !</span>
<span class="line">h264parse config-interval=-1 !</span>
<span class="line">video/x-h264,stream-format=byte-stream,alignment=au !</span>
<span class="line">appsink sync=TRUE emit-signals=TRUE name=appsink-video</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Raspberry Pi 5에는 이전 세대에 있던 H.264 하드웨어 인코더가 없어서 소프트웨어 인코딩(x264enc)으로 돌아가야 한다. Raspberry Pi도 Pi 5의 H.264 인코딩은 CPU 인코딩 성능 문서로 안내한다. 보드를 고를 때 미리 확인한다. 하드웨어 인코더 일반론은 <a href="/study/webrtc/13-native-webrtc">13장</a>에서 다뤘다.</p><h3 id="실전에서-걸리는-지점" tabindex="-1"><a class="header-anchor" href="#실전에서-걸리는-지점"><span>실전에서 걸리는 지점</span></a></h3><ol><li><strong>타임스탬프.</strong> 샘플 콜백은 버퍼 PTS를 계산만 하고 쓰지 않는다. 대신 세션마다 <code>SAMPLE_VIDEO_FRAME_DURATION</code>(25 fps 가정)씩 타임스탬프를 늘린다. 실제 카메라는 프레임 간격이 흔들리고 조도에 따라 fps가 바뀌기도 하므로, 위 코드처럼 running time(ns)을 100 ns 단위로 바꿔 넣는 편이 수신 측 지터 버퍼와 립싱크에 맞다.</li><li><strong>인코더 하나를 N 세션이 공유한다.</strong> 샘플은 TWCC 피드백(<code>sampleOnPeerCongestionFeedback</code>)으로 세션별 목표 비트레이트를 계산하고(비디오 384~2,500 kbps 범위), 이름이 <code>sampleVideoEncoder</code>인 인코더의 <code>bitrate</code> 속성을 바꾼다. 그런데 인코더는 하나라서 마지막에 쓴 세션의 값이 이긴다. LTE로 접속한 운영자 한 명 때문에 사무실 운영자 화질까지 떨어지거나, 그 반대가 된다. &quot;가장 느린 viewer에 맞춘다&quot; 같은 정책을 정해 세션별 추정값을 모아서 하나로 결정하는 코드를 직접 넣어야 한다. 비트레이트 단위도 인코더마다 다르다. x264enc의 <code>bitrate</code>는 kbit/s, nvv4l2h264enc는 bit/s이고, v4l2h264enc에는 <code>bitrate</code> 속성이 없고 <code>extra-controls</code>로 준다. 혼잡 제어 원리는 <a href="/study/webrtc/09-quality-latency">09장</a>에서 다뤘다.</li><li><strong>첫 화면까지의 시간은 GOP가 정한다.</strong> DTLS가 끝나기 전 <code>writeFrame</code>은 <code>STATUS_SRTP_NOT_READY_YET</code>을 돌려준다. 그 뒤로도 다음 IDR이 올 때까지 viewer는 디코딩을 시작하지 못한다. GOP가 2초면 최악 2초를 더 기다린다. 새 세션이 연결될 때, 또는 viewer가 PLI를 보낼 때(<code>transceiverOnPictureLoss</code> 콜백) 인코더에 강제 키프레임을 요청하면 이 시간이 줄어든다. GStreamer에서는 <code>gst_video_event_new_upstream_force_key_unit()</code>으로 만든 upstream 이벤트를 인코더 쪽으로 보낸다. 샘플에는 이 처리가 없다.</li><li><strong>지연이 쌓이지 않게 한다.</strong> CPU가 밀리면 큐에 프레임이 쌓여 지연이 계속 늘어난다. 인코더 앞 <code>queue</code>를 <code>leaky=downstream max-size-buffers=1</code>처럼 작게 두면 오래된 프레임을 버리고 최신 프레임을 보낸다. 샘플도 오디오 쪽에 <code>queue leaky=2 max-size-buffers=400</code>을 쓴다.</li><li><strong>콜백은 GStreamer 스트리밍 스레드에서 돈다.</strong> 콜백 안에서 N개 세션의 <code>writeFrame</code>이 끝나야 다음 버퍼가 나온다. 콜백 안에서 블로킹 I/O나 긴 로그를 하지 않는다.</li><li><strong>IP 카메라는 재인코딩을 피할 수 있다.</strong> 샘플의 <code>rtspsrc</code> 모드는 <code>uridecodebin</code>으로 디코딩한 뒤 x264enc로 다시 인코딩해서 CPU를 많이 쓴다. 카메라가 이미 B-프레임 없는 H.264를 낸다면 <code>rtspsrc ! rtph264depay ! h264parse config-interval=-1 ! video/x-h264,stream-format=byte-stream,alignment=au ! appsink</code>로 그대로 넘길 수 있다. 대신 비트레이트 적응은 포기해야 한다(카메라 인코더를 SDK가 조절할 수 없다). 카메라가 High 프로파일을 내면 SDP가 광고하는 <code>42e01f</code>와 어긋나므로 브라우저 디코딩 여부를 실기로 확인한다.</li></ol><p>인제스트 모드 채널용으로 <code>kvsWebrtcStorageAudioVideoMaster</code>, <code>kvsWebrtcStorageVideoOnlyMaster</code>와 각 GstSample도 있다. <code>JoinStorageSession</code> API 문서는 &quot;Both audio and video tracks are currently required&quot;라고 적는데 SDK에는 비디오만 보내는 샘플이 있어 둘이 엇갈린다. 자세한 내용은 <a href="/study/webrtc/21-kvs-ingestion-storage">21장</a>에서 다룬다.</p><h2 id="_4-aws-iot-credential-provider로-임시-자격증명-받기" tabindex="-1"><a class="header-anchor" href="#_4-aws-iot-credential-provider로-임시-자격증명-받기"><span>4. AWS IoT Credential Provider로 임시 자격증명 받기</span></a></h2><p>샘플은 <code>AWS_ACCESS_KEY_ID</code>·<code>AWS_SECRET_ACCESS_KEY</code> 환경변수로 동작하지만, 수천 대 농기계에 IAM 사용자의 장기 키를 심으면 한 대만 털려도 키를 돌려야 하고, 회전도 사실상 불가능하다. KVS는 인증서 인증을 지원하지 않고 SigV4만 받는다. 그래서 디바이스가 이미 가진 X.509 인증서로 AWS IoT credentials provider에 TLS 상호 인증을 하고, provider가 IAM 역할을 대신 assume해 임시 자격증명을 내주는 방식을 쓴다. MQTT로 IoT Core에 붙을 때 쓰는 그 인증서를 그대로 재사용한다. IoT 인증서·Thing·정책의 기본은 <a href="/posts/tech/2025-06-27-iot">AWS IoT Core 완전 정복</a>에서 정리했다.</p><p><img src="`+d+'" alt="AWS IoT Credential Provider 연동 흐름. 디바이스(X.509 인증서·개인키, Thing tractor-0017)가 ① x-amzn-iot-thingname 헤더를 붙여 IoT credentials provider 엔드포인트의 /role-aliases/{alias}/credentials에 mTLS GET을 보낸다. provider는 인증서에 붙은 IoT 정책의 iot:AssumeRoleWithCertificate를 확인하고 ② role alias가 가리키는 IAM 역할(신뢰 주체 credentials.iot.amazonaws.com)을 AssumeRole한다. ③ accessKeyId·secretAccessKey·sessionToken·expiration을 돌려받은 디바이스는 ④ SigV4로 KVS 시그널링에 Describe·GetEndpoint·GetIceServerConfig·ConnectAsMaster를 호출하고, 역할의 IAM 정책은 리소스를 channel/${credentials-iot:ThingName}/*로 제한한다"><img src="'+u+`" alt="AWS IoT Credential Provider 연동 흐름. 디바이스(X.509 인증서·개인키, Thing tractor-0017)가 ① x-amzn-iot-thingname 헤더를 붙여 IoT credentials provider 엔드포인트의 /role-aliases/{alias}/credentials에 mTLS GET을 보낸다. provider는 인증서에 붙은 IoT 정책의 iot:AssumeRoleWithCertificate를 확인하고 ② role alias가 가리키는 IAM 역할(신뢰 주체 credentials.iot.amazonaws.com)을 AssumeRole한다. ③ accessKeyId·secretAccessKey·sessionToken·expiration을 돌려받은 디바이스는 ④ SigV4로 KVS 시그널링에 Describe·GetEndpoint·GetIceServerConfig·ConnectAsMaster를 호출하고, 역할의 IAM 정책은 리소스를 channel/\${credentials-iot:ThingName}/*로 제한한다"></p><h3 id="설정-순서" tabindex="-1"><a class="header-anchor" href="#설정-순서"><span>설정 순서</span></a></h3><p><strong>1. IAM 역할 신뢰 정책</strong>(<code>trust.json</code>). credentials provider만 이 역할을 assume할 수 있다.</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json" data-title="json"><pre><code><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;Version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2012-10-17&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;Statement&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;Effect&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Allow&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;Principal&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token property">&quot;Service&quot;</span><span class="token operator">:</span> <span class="token string">&quot;credentials.iot.amazonaws.com&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;Action&quot;</span><span class="token operator">:</span> <span class="token string">&quot;sts:AssumeRole&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 역할 권한 정책</strong>(<code>kvs-master.json</code>). C SDK README의 IoT 역할 예시에서 <code>CreateSignalingChannel</code>을 뺐다. 채널은 백엔드가 만든다는 전제다(20장). README도 기존 채널을 쓰면 이 권한을 빼도 된다고 적는다.</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json" data-title="json"><pre><code><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;Version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;2012-10-17&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;Statement&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token property">&quot;Effect&quot;</span><span class="token operator">:</span> <span class="token string">&quot;Allow&quot;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;Action&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">        <span class="token string">&quot;kinesisvideo:DescribeSignalingChannel&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;kinesisvideo:GetSignalingChannelEndpoint&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;kinesisvideo:GetIceServerConfig&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;kinesisvideo:ConnectAsMaster&quot;</span></span>
<span class="line">      <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token property">&quot;Resource&quot;</span><span class="token operator">:</span> <span class="token string">&quot;arn:aws:kinesisvideo:ap-northeast-2:123456789012:channel/\${credentials-iot:ThingName}/*&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>채널 ARN은 <code>channel/&lt;채널이름&gt;/&lt;생성시각&gt;</code> 형식이라 끝에 <code>/*</code>를 붙인다. 채널을 지웠다 같은 이름으로 다시 만들면 생성시각이 바뀌는데, 와일드카드라서 정책을 고칠 필요가 없다.</p><p><strong>3. role alias, IoT 정책, 인증서 연결.</strong></p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">aws iam create-role --role-name KvsDeviceRole --assume-role-policy-document file://trust.json</span>
<span class="line">aws iam put-role-policy --role-name KvsDeviceRole --policy-name kvs-master <span class="token punctuation">\\</span></span>
<span class="line">  --policy-document file://kvs-master.json</span>
<span class="line"></span>
<span class="line"><span class="token comment"># 디바이스는 역할 ARN 대신 alias만 안다. 역할을 바꿔도 펌웨어를 고칠 필요가 없다</span></span>
<span class="line">aws iot create-role-alias --role-alias KvsDeviceRoleAlias <span class="token punctuation">\\</span></span>
<span class="line">  --role-arn arn:aws:iam::123456789012:role/KvsDeviceRole <span class="token punctuation">\\</span></span>
<span class="line">  --credential-duration-seconds <span class="token number">3600</span></span>
<span class="line"></span>
<span class="line">aws iot create-policy --policy-name KvsAssumeRoleWithCert --policy-document <span class="token string">&#39;{</span>
<span class="line">  &quot;Version&quot;: &quot;2012-10-17&quot;,</span>
<span class="line">  &quot;Statement&quot;: [{</span>
<span class="line">    &quot;Effect&quot;: &quot;Allow&quot;,</span>
<span class="line">    &quot;Action&quot;: &quot;iot:AssumeRoleWithCertificate&quot;,</span>
<span class="line">    &quot;Resource&quot;: &quot;arn:aws:iot:ap-northeast-2:123456789012:rolealias/KvsDeviceRoleAlias&quot;</span>
<span class="line">  }]</span>
<span class="line">}&#39;</span></span>
<span class="line">aws iot attach-policy --policy-name KvsAssumeRoleWithCert <span class="token parameter variable">--target</span> <span class="token operator">&lt;</span>certificate-arn<span class="token operator">&gt;</span></span>
<span class="line">aws iot attach-thing-principal --thing-name tractor-0017 <span class="token parameter variable">--principal</span> <span class="token operator">&lt;</span>certificate-arn<span class="token operator">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 계정 전용 credentials provider 엔드포인트 (IoT 데이터 엔드포인트와 다르다)</span></span>
<span class="line">aws iot describe-endpoint --endpoint-type iot:CredentialProvider</span>
<span class="line"><span class="token comment"># → {&quot;endpointAddress&quot;: &quot;&lt;prefix&gt;.credentials.iot.ap-northeast-2.amazonaws.com&quot;}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>role alias 이름은 1~128자이고 영숫자와 <code>=</code>, <code>@</code>, <code>-</code>만 쓸 수 있다. <code>--credential-duration-seconds</code>는 최소 900초, 최대 43,200초(12시간), 기본 3,600초이며 IAM 역할의 최대 세션 시간보다 길 수 없다. role alias를 만드는 사용자에게는 그 역할에 대한 <code>iam:PassRole</code> 권한이 필요하다.</p><p><strong>4. curl로 먼저 확인한다.</strong> SDK에 넣기 전에 디바이스에서 직접 호출해 보면 인증서·정책 문제를 SDK 로그 없이 가를 수 있다.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token function">curl</span> <span class="token parameter variable">--cert</span> certificate.pem.crt <span class="token parameter variable">--key</span> private.pem.key <span class="token parameter variable">--cacert</span> AmazonRootCA1.pem <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&quot;x-amzn-iot-thingname: tractor-0017&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  https://<span class="token operator">&lt;</span>prefix<span class="token operator">&gt;</span>.credentials.iot.ap-northeast-2.amazonaws.com/role-aliases/KvsDeviceRoleAlias/credentials</span>
<span class="line"><span class="token comment"># {&quot;credentials&quot;:{&quot;accessKeyId&quot;:&quot;...&quot;,&quot;secretAccessKey&quot;:&quot;...&quot;,&quot;sessionToken&quot;:&quot;...&quot;,&quot;expiration&quot;:&quot;...&quot;}}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="sdk에-연결하기" tabindex="-1"><a class="header-anchor" href="#sdk에-연결하기"><span>SDK에 연결하기</span></a></h3><p>샘플을 IoT 모드로 빌드하고 환경변수를 준다.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line">cmake <span class="token punctuation">..</span> <span class="token parameter variable">-DIOT_CORE_ENABLE_CREDENTIALS</span><span class="token operator">=</span>ON <span class="token parameter variable">-DPARALLEL_BUILD</span><span class="token operator">=</span>ON</span>
<span class="line"><span class="token function">make</span> <span class="token parameter variable">-j</span></span>
<span class="line"></span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_IOT_CORE_CREDENTIAL_ENDPOINT</span><span class="token operator">=</span><span class="token operator">&lt;</span>prefix<span class="token operator">&gt;</span>.credentials.iot.ap-northeast-2.amazonaws.com</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_IOT_CORE_CERT</span><span class="token operator">=</span>/etc/kvs/certificate.pem.crt</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_IOT_CORE_PRIVATE_KEY</span><span class="token operator">=</span>/etc/kvs/private.pem.key</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_IOT_CORE_ROLE_ALIAS</span><span class="token operator">=</span>KvsDeviceRoleAlias</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_IOT_CORE_THING_NAME</span><span class="token operator">=</span>tractor-0017</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">AWS_DEFAULT_REGION</span><span class="token operator">=</span>ap-northeast-2</span>
<span class="line"></span>
<span class="line">./samples/kvsWebrtcClientMaster      <span class="token comment"># 인자가 없으면 AWS_IOT_CORE_THING_NAME을 채널 이름으로 쓴다</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>이 모드로 빌드하면 <code>AWS_ACCESS_KEY_ID</code> 같은 키 환경변수는 무시된다. 샘플 코드(<code>createSampleConfiguration</code>)를 보면 <code>AWS_IOT_CORE_CERTIFICATE_ID</code> 환경변수가 설정돼 있을 때 그 값으로 채널 이름을 덮어쓴다. 의도치 않게 이 변수가 남아 있으면 엉뚱한 채널로 붙으니 주의한다. <code>-DIOT_CORE_ENABLE_CREDENTIALS</code>는 샘플이 어떤 provider를 만들지 정하는 옵션일 뿐이다. 직접 작성한 앱에서는 2절 골격처럼 <code>createLwsIotCredentialProvider(endpoint, certPath, privateKeyPath, caCertPath, roleAlias, thingName, &amp;provider)</code>를 부르면 된다.</p><p>provider는 받은 자격증명을 캐시하고 만료 전에 다시 받아 온다. producer-c의 <code>IotCredentialProvider.c</code>를 보면 만료 시각에서 남은 시간의 1~20%를 랜덤 지터로 빼서 유효 기간을 잡는다. 같은 시각에 켜진 디바이스 수천 대가 동시에 갱신 요청을 몰아 보내지 않게 하는 장치다.</p><h3 id="정책-변수-credentials-iot-thingname-이-막아-주는-것" tabindex="-1"><a class="header-anchor" href="#정책-변수-credentials-iot-thingname-이-막아-주는-것"><span>정책 변수 <code>\${credentials-iot:ThingName}</code>이 막아 주는 것</span></a></h3><p>KVS <code>ConnectAsMaster</code> 문서에 따르면 같은 채널에 master가 두 번 붙으면 가장 최근 요청이 이기고 기존 연결 정보를 덮어쓴다(<a href="/study/webrtc/17-kvs-architecture">17장</a>). 디바이스 역할이 <code>channel/*</code>에 <code>ConnectAsMaster</code>를 허용하면, 인증서 하나가 유출됐을 때 그 인증서로 다른 농기계 채널의 master 자리를 빼앗아 가짜 영상을 내보낼 수 있다. 리소스를 <code>channel/\${credentials-iot:ThingName}/*</code>로 묶으면 인증서마다 자기 Thing 이름과 같은 채널에만 접근한다. C SDK README도 &quot;KVS recommendation is to use iot thing name as channel name&quot;이라고 적는다.</p><p>이 변수에는 조건이 몇 가지 붙는다.</p><ul><li><code>credentials-iot:ThingName</code>, <code>credentials-iot:ThingTypeName</code>, <code>credentials-iot:AwsCertificateId</code> 세 변수는 IAM 정책에서만 동작한다. IoT Core 정책에서는 쓸 수 없다.</li><li>ThingName·ThingTypeName은 디바이스가 <code>x-amzn-iot-thingname</code> 헤더를 보낼 때만 채워진다. SDK의 provider는 <code>thingName</code> 인자로 이 헤더를 붙인다.</li><li>헤더의 Thing 이름이 인증서에 붙은 Thing과 다르면 403이 난다. 그래서 디바이스가 남의 Thing 이름을 사칭할 수 없다.</li><li>출처를 구분해 두면, 채널 리소스에 이 변수를 쓴 예시는 awslabs C SDK README에 있다. KVS 개발자 가이드(how-iot)의 예시는 스트림 리소스(<code>stream/\${credentials-iot:ThingName}/*</code>)다.</li></ul><div class="hint-container warning"><p class="hint-container-title">Thing 이름과 채널 이름의 허용 문자가 다르다</p><p>IoT Thing 이름은 1~128자 <code>[a-zA-Z0-9:_-]+</code>, 시그널링 채널 이름은 1~256자 <code>[a-zA-Z0-9_.-]+</code>다. Thing 이름에 콜론(<code>:</code>)이 들어가면 같은 이름의 채널을 만들 수 없고, 채널 이름에 점(<code>.</code>)을 쓰면 같은 이름의 Thing을 만들 수 없다. Thing 이름 = 채널 이름 규칙을 쓰려면 이름을 <code>[a-zA-Z0-9_-]</code>, 128자 이하로 제한한다. 예: <code>tractor-0017</code>.</p></div><p><strong>시계가 맞지 않으면 아무것도 안 된다.</strong> mTLS 인증서 검증과 SigV4 서명 모두 정확한 시각이 필요하다. RTC 배터리가 없는 보드는 부팅 직후 1970년으로 시작해서 &quot;certificate is not yet valid&quot;로 TLS가 실패하거나 SigV4가 거부된다. systemd 환경이면 <code>systemd-time-wait-sync</code> 같은 장치로 NTP 동기화를 기다린 뒤 서비스를 띄운다. 임베디드 시계 동기 문제는 <a href="/study/webrtc/13-native-webrtc">13장</a>에서도 다뤘다. SDK API는 인증서와 개인키를 파일 경로로 받으므로 개인키 파일 권한을 서비스 계정만 읽도록 제한한다.</p><h2 id="_5-크로스-컴파일·리소스-제약·로그-레벨" tabindex="-1"><a class="header-anchor" href="#_5-크로스-컴파일·리소스-제약·로그-레벨"><span>5. 크로스 컴파일·리소스 제약·로그 레벨</span></a></h2><h3 id="크로스-컴파일" tabindex="-1"><a class="header-anchor" href="#크로스-컴파일"><span>크로스 컴파일</span></a></h3><p>README에 따르면 SDK와 모든 의존성 빌드가 <code>CC</code>·<code>CXX</code> 환경변수를 따른다. 여기에 OpenSSL과 libsrtp의 대상 플랫폼을 알려 주는 세 변수를 더 준다.</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh" data-title="sh"><pre><code><span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">CC</span><span class="token operator">=</span>aarch64-linux-gnu-gcc</span>
<span class="line"><span class="token builtin class-name">export</span> <span class="token assign-left variable">CXX</span><span class="token operator">=</span>aarch64-linux-gnu-g++</span>
<span class="line"></span>
<span class="line">cmake <span class="token punctuation">..</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DBUILD_OPENSSL_PLATFORM</span><span class="token operator">=</span>linux-aarch64 <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DBUILD_LIBSRTP_HOST_PLATFORM</span><span class="token operator">=</span>x86_64-unknown-linux-gnu <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DBUILD_LIBSRTP_DESTINATION_PLATFORM</span><span class="token operator">=</span>aarch64-unknown-linux-gnu <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DBUILD_STATIC_LIBS</span><span class="token operator">=</span>TRUE <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DBUILD_SAMPLE</span><span class="token operator">=</span>OFF <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-DUSE_OPENSSL3</span><span class="token operator">=</span>ON</span>
<span class="line"><span class="token function">make</span> <span class="token parameter variable">-j</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>BUILD_OPENSSL_PLATFORM</code>은 OpenSSL <code>Configure</code>의 타깃 이름이고, libsrtp 두 변수는 빌드 호스트와 대상의 트리플릿이다. 위 값은 x86_64에서 aarch64 Linux로 빌드할 때의 예시다. README는 변수 이름만 적고, 구체적인 값은 매 커밋을 크로스 컴파일하는 자기들 CI 설정을 참고하라고 한다. 알려진 특수 사례도 README에 있다.</p><table><thead><tr><th>상황</th><th>옵션</th></tr></thead><tbody><tr><td>macOS M1에서 OpenSSL·libwebsockets 빌드 실패</td><td><code>-DBUILD_OPENSSL_PLATFORM=darwin64-arm64-cc</code></td></tr><tr><td>64비트 하드웨어 위 32비트 Raspbian 11</td><td><code>-DBUILD_OPENSSL_PLATFORM=linux-armv4</code> (OpenSSL이 64비트 ARM 어셈블리를 내지 않게)</td></tr><tr><td>uClibc 툴체인</td><td><code>-DADD_MUCLIBC</code></td></tr><tr><td>대상 보드에서 동작 검증</td><td><code>-DBUILD_TEST=TRUE</code> → 보드에서 <code>./tst/webrtc_client_test</code></td></tr></tbody></table><p>GStreamer 샘플까지 크로스 빌드하려면 대상 보드의 GStreamer 개발 패키지가 든 sysroot를 <code>pkg-config</code>가 보게 해야 한다(<code>PKG_CONFIG_SYSROOT_DIR</code>, <code>PKG_CONFIG_LIBDIR</code>). 보통은 SDK만 크로스 빌드하고 GStreamer 연동 앱은 Yocto 레시피나 보드 위 네이티브 빌드로 만드는 편이 덜 고생스럽다.</p><h3 id="메모리·cpu-조정" tabindex="-1"><a class="header-anchor" href="#메모리·cpu-조정"><span>메모리·CPU 조정</span></a></h3><table><thead><tr><th>항목</th><th>기본값</th><th>조정 방법</th></tr></thead><tbody><tr><td>RTP rolling buffer(NACK 재전송용)</td><td>3초, 비디오 5 Mibps · 오디오 1 Mibps, MTU 1,200 B</td><td>트랜시버별 <code>configureTransceiverRollingBuffer</code> (0.1~10초, 100 Kibps~240 Mibps)</td></tr><tr><td>SDP m= 섹션 슬롯</td><td>5</td><td><code>-DMAX_SDP_SESSION_MEDIA_COUNT</code>. 슬롯당 스택 약 140 KB</td></tr><tr><td>스레드 스택</td><td>시스템 기본</td><td><code>-DKVS_STACK_SIZE</code>, 개별 스레드는 <code>THREAD_CREATE_WITH_PARAMS()</code></td></tr><tr><td>스레드풀</td><td>꺼짐(켜면 최소 3, 최대 10)</td><td><code>-DENABLE_KVS_THREADPOOL=ON</code>, <code>AWS_KVS_WEBRTC_THREADPOOL_MIN_THREADS</code>·<code>MAX_THREADS</code></td></tr><tr><td>ICE 통계 계산</td><td>켜짐</td><td><code>-DENABLE_STATS_CALCULATION_CONTROL</code> + <code>enableIceStats = FALSE</code></td></tr><tr><td>DTLS 인증서</td><td>연결마다 생성(저사양에서 5~15초)</td><td>미리 생성 큐(<code>KVS_PRE_GENERATE_CERT_*</code>)</td></tr></tbody></table><p>rolling buffer 용량은 README 공식으로 &quot;버퍼 시간 × 최고 비트레이트 / 8 / MTU&quot;개의 RTP 패킷이다. README 예시처럼 1초 × 5 Mibps / 8 / 1,200 B면 546개다. 기본 3초면 비디오 트랜시버 하나에 약 1,638개 슬롯이고, 패킷이 MTU 크기로 꽉 찬다고 치면 상한이 약 2 MB다. 이게 viewer마다 하나씩 붙으니 viewer 10명이면 비디오 버퍼만 수십 MB까지 갈 수 있다. 실제 스트림이 1 Mbps라면 비트레이트 파라미터를 그만큼 낮춰 메모리를 아낀다. README는 너무 작게 잡으면 네트워크가 나쁠 때 NACK에 응답하지 못해 화면이 깨진다고 경고한다.</p><p>메모리나 CPU가 어디서 새는지 찾을 때는 <code>-DLINK_PROFILER=ON</code>으로 gperftools를 링크하고 <code>HEAPPROFILE=/tmp/heap.prof</code>나 <code>CPUPROFILE=/tmp/cpu.prof</code> 환경변수로 실행한다.</p><h3 id="로그-레벨" tabindex="-1"><a class="header-anchor" href="#로그-레벨"><span>로그 레벨</span></a></h3><p><code>AWS_KVS_LOG_LEVEL</code>에 숫자로 준다. 기본은 WARN(4)이다.</p><table><thead><tr><th>값</th><th>레벨</th><th>용도</th></tr></thead><tbody><tr><td>1</td><td>VERBOSE</td><td>함수 진입·탈출까지. <code>add_definitions(-DLOG_STREAMING)</code>과 함께 쓰면 매우 많다</td></tr><tr><td>2</td><td>DEBUG</td><td>개발 중 연결 문제 추적</td></tr><tr><td>3</td><td>INFO</td><td>현장 시험</td></tr><tr><td>4</td><td>WARN</td><td>기본값, 제품 기본</td></tr><tr><td>5</td><td>ERROR</td><td></td></tr><tr><td>6</td><td>FATAL</td><td></td></tr><tr><td>7</td><td>SILENT</td><td></td></tr><tr><td>8</td><td>PROFILE</td><td>단계별 소요 시간</td></tr></tbody></table><p>v1.8.0부터 SDK는 기본으로 연결 수립 단계별 소요 시간을 <code>build</code> 디렉터리의 <code>kvsFileLogFilter.x</code> 파일에 남긴다. 샘플의 <code>initSignaling</code>이 찍는 <code>[Signaling Get token] … ms</code>, <code>[Signaling Describe] … ms</code>, <code>[Signaling Connect] … ms</code> 같은 PROFILE 로그가 그것이다. &quot;운영자가 버튼을 누르고 화면이 뜨기까지 왜 4초나 걸리나&quot;를 따질 때 가장 먼저 볼 자료다. 일반 로그도 파일로 남기는 환경변수는 README 본문에 <code>AWS_ENABLE_FILE_LOGGING</code>, 환경변수 표에 <code>ENABLE_FILE_LOGGING</code>으로 이름이 엇갈려 적혀 있다. 쓰는 버전의 소스에서 확인한다.</p><p>현장 디버깅에 쓰는 스위치를 모아 두면 다음과 같다.</p><ul><li><code>DEBUG_LOG_SDP=TRUE</code>: 주고받는 SDP를 출력한다. SDP에는 IP 주소와 <code>ice-pwd</code>가 들어 있으니 중앙 로그로 보내지 않는다.</li><li><code>KVS_ICE_TRANSPORT_POLICY=relay</code>: TURN 후보만 쓰게 강제한다. 방화벽 뒤 농장에서 TURN 경로가 열려 있는지 확인할 때 쓴다(<a href="/study/webrtc/07-turn">07장</a>).</li><li><code>samples/discoverNatBehavior.c</code>: 공개 API <code>discoverNatBehavior</code>로 현장 네트워크의 NAT 매핑·필터링 동작을 판별한다(<a href="/study/webrtc/05-nat-stun">05장</a>).</li><li>ICE 타임아웃: 로그에 기본값(<code>iceLocalCandidateGatheringTimeout</code> 10,000 ms, <code>iceConnectionCheckTimeout</code> 12,000 ms, <code>iceCandidateNominationTimeout</code> 12,000 ms, 검사 주기 50 ms)이 찍힌다. LTE에서 relay 후보 수집이 느리면 <code>iceCandidateNominationTimeout</code>을 relay 수집 시간보다 길게 잡는다.</li><li>네트워크 인터페이스 필터: <code>KvsRtcConfiguration.iceSetInterfaceFilterFunc</code>로 <code>docker0</code>처럼 쓸모없는 인터페이스를 후보 수집에서 빼면 수집 시간이 준다.</li></ul><h3 id="방화벽에-열어야-할-것" tabindex="-1"><a class="header-anchor" href="#방화벽에-열어야-할-것"><span>방화벽에 열어야 할 것</span></a></h3><p>농장 사무실이나 통신사 사설망은 아웃바운드도 막혀 있는 경우가 많다. README의 요구사항에 IoT 자격증명과 시각 동기를 더하면 다음과 같다.</p><table><thead><tr><th>대상</th><th>프로토콜·포트</th><th>예시 호스트</th></tr></thead><tbody><tr><td>KVS 컨트롤 플레인</td><td>TCP 443</td><td><code>kinesisvideo.ap-northeast-2.amazonaws.com</code></td></tr><tr><td>채널 HTTPS 엔드포인트</td><td>TCP 443</td><td><code>r-xxxxxxxx.kinesisvideo.&lt;region&gt;.amazonaws.com</code></td></tr><tr><td>채널 WSS 엔드포인트</td><td>TCP 443</td><td><code>m-xxxxxxxx.kinesisvideo.&lt;region&gt;.amazonaws.com</code></td></tr><tr><td>STUN</td><td>UDP 443</td><td><code>stun.kinesisvideo.&lt;region&gt;.amazonaws.com</code></td></tr><tr><td>TURN</td><td>UDP/TCP 443</td><td><code>&lt;ip&gt;.t-xxxxxxxx.kinesisvideo.&lt;region&gt;.amazonaws.com</code></td></tr><tr><td>IoT credentials provider</td><td>TCP 443 (mTLS)</td><td><code>&lt;prefix&gt;.credentials.iot.&lt;region&gt;.amazonaws.com</code></td></tr><tr><td>NTP</td><td>UDP 123</td><td>사내 또는 공용 NTP 서버</td></tr></tbody></table><p>README는 공통 분모를 <code>*.kinesisvideo.&lt;region&gt;.amazonaws.com</code>의 443 포트로 요약한다. IPv6는 출처끼리 서술이 다르다. KVS System requirements 문서는 &quot;IPv6 addresses aren&#39;t currently supported for STUN and TURN servers&quot;라고 적는 반면, C SDK는 <code>KVS_DUALSTACK_ENDPOINTS=ON</code>으로 dual-stack 엔드포인트를 쓰고 IPv6 후보를 수집하는 옵션을 제공한다(<code>KVS_DISABLE_IPV4_TURN</code>, <code>KVS_DISABLE_IPV6_TURN</code>도 있다). SDK 쪽이 더 최근 변경일 가능성이 있지만, IPv6 전용망을 전제로 설계하기 전에 실측한다.</p><div class="hint-container tip"><p class="hint-container-title">핵심 정리</p><ul><li>KVS C SDK는 <code>kvsWebrtcClient</code>(WebRTC 스택)와 <code>kvsWebrtcSignalingClient</code>(KVS 시그널링)로 나뉘고, 자격증명·SigV4는 producer-c의 <code>kvsCommonLws</code>가 맡는다. 인코딩은 앱 몫이고 SDK는 인코딩된 프레임을 받아 보낸다.</li><li>master 흐름은 credential provider → <code>createSignalingClientSync</code> → <code>signalingClientFetchSync</code> → <code>signalingClientConnectSync</code> → 오퍼마다 <code>createPeerConnection</code>·<code>addTransceiver</code>·<code>setRemoteDescription</code>·<code>setLocalDescription</code>·<code>createAnswer</code> → <code>writeFrame</code>이다.</li><li>viewer마다 PeerConnection과 <code>writeFrame</code>이 하나씩 늘어 업링크·CPU·메모리가 viewer 수만큼 곱해진다. 인코더는 하나라서 세션별 대역폭 추정을 하나로 합치는 정책이 필요하다.</li><li>GStreamer 연동은 <code>appsink</code> + <code>&quot;new-sample&quot;</code> 콜백이다. 캡스는 byte-stream·au·baseline, B-프레임 0, <code>h264parse config-interval=-1</code>, 타임스탬프는 버퍼 running time을 100 ns 단위로 쓴다.</li><li>디바이스 자격증명은 IoT credentials provider + role alias로 받고, IAM 정책 리소스를 <code>channel/\${credentials-iot:ThingName}/*</code>로 묶어 인증서 하나가 다른 채널의 master를 빼앗지 못하게 한다. Thing·채널 이름은 <code>[a-zA-Z0-9_-]</code>로 제한한다.</li><li>시그널링 연결은 최대 1시간·idle 10분이 hard 한도이므로 재연결 감시 루프가 필수다. 부팅 직후에는 NTP 동기화를 기다린다.</li></ul></div><h2 id="다음-챕터" tabindex="-1"><a class="header-anchor" href="#다음-챕터"><span>다음 챕터</span></a></h2><p><a href="/study/webrtc/20-kvs-viewer-backend">뷰어·백엔드 구현</a>에서는 반대편인 운영자 브라우저를 JS SDK <code>SignalingClient</code>로 구현하고, 브라우저에 줄 자격증명을 Cognito Identity Pool·백엔드 STS 세션 정책·서명 URL 중 무엇으로 발급할지, 디바이스 등록과 함께 채널을 만들고 지우는 프로비저닝 백엔드를 어떻게 설계할지 다룬다.</p>`,111)]))}const b=s(k,[["render",v],["__file","19-kvs-c-sdk.html.vue"]]),g=JSON.parse('{"path":"/study/webrtc/19-kvs-c-sdk.html","title":"디바이스 측 구현: KVS C SDK","lang":"en-US","frontmatter":{"title":"디바이스 측 구현: KVS C SDK","description":"amazon-kinesis-video-streams-webrtc-sdk-c의 구조·의존성·빌드 옵션, kvsWebrtcClientMaster 샘플이 자격증명에서 writeFrame까지 가는 흐름, GStreamer appsink로 하드웨어 인코더 출력을 넘기는 구조, AWS IoT Credential Provider로 인증서 기반 임시 자격증명을 받는 방법, 크로스 컴파일·메모리·로그 레벨 운영 팁을 다룬다.","date":"2026-10-19T00:00:00.000Z","tags":["WebRTC","AWS","KVS","Embedded","GStreamer","IoT"],"prev":"/study/webrtc/18-kvs-signaling-api","next":"/study/webrtc/20-kvs-viewer-backend"},"headers":[{"level":1,"title":"디바이스 측 구현: KVS C SDK","slug":"디바이스-측-구현-kvs-c-sdk","link":"#디바이스-측-구현-kvs-c-sdk","children":[{"level":2,"title":"1. SDK 구조와 의존성","slug":"_1-sdk-구조와-의존성","link":"#_1-sdk-구조와-의존성","children":[{"level":3,"title":"저장소와 빌드 결과물","slug":"저장소와-빌드-결과물","link":"#저장소와-빌드-결과물","children":[]},{"level":3,"title":"서드파티 의존성","slug":"서드파티-의존성","link":"#서드파티-의존성","children":[]},{"level":3,"title":"빌드","slug":"빌드","link":"#빌드","children":[]}]},{"level":2,"title":"2. kvsWebrtcClientMaster 샘플 흐름","slug":"_2-kvswebrtcclientmaster-샘플-흐름","link":"#_2-kvswebrtcclientmaster-샘플-흐름","children":[{"level":3,"title":"시그널링 클라이언트의 상태 머신","slug":"시그널링-클라이언트의-상태-머신","link":"#시그널링-클라이언트의-상태-머신","children":[]},{"level":3,"title":"핵심 API 호출 골격","slug":"핵심-api-호출-골격","link":"#핵심-api-호출-골격","children":[]},{"level":3,"title":"샘플 코드에서 읽어 둘 동작","slug":"샘플-코드에서-읽어-둘-동작","link":"#샘플-코드에서-읽어-둘-동작","children":[]},{"level":3,"title":"viewer 샘플은 언제 쓰나","slug":"viewer-샘플은-언제-쓰나","link":"#viewer-샘플은-언제-쓰나","children":[]}]},{"level":2,"title":"3. GStreamer 샘플과 하드웨어 인코더 연동","slug":"_3-gstreamer-샘플과-하드웨어-인코더-연동","link":"#_3-gstreamer-샘플과-하드웨어-인코더-연동","children":[{"level":3,"title":"appsink → writeFrame 구조","slug":"appsink-→-writeframe-구조","link":"#appsink-→-writeframe-구조","children":[]},{"level":3,"title":"하드웨어 인코더 파이프라인","slug":"하드웨어-인코더-파이프라인","link":"#하드웨어-인코더-파이프라인","children":[]},{"level":3,"title":"실전에서 걸리는 지점","slug":"실전에서-걸리는-지점","link":"#실전에서-걸리는-지점","children":[]}]},{"level":2,"title":"4. AWS IoT Credential Provider로 임시 자격증명 받기","slug":"_4-aws-iot-credential-provider로-임시-자격증명-받기","link":"#_4-aws-iot-credential-provider로-임시-자격증명-받기","children":[{"level":3,"title":"설정 순서","slug":"설정-순서","link":"#설정-순서","children":[]},{"level":3,"title":"SDK에 연결하기","slug":"sdk에-연결하기","link":"#sdk에-연결하기","children":[]},{"level":3,"title":"정책 변수 ${credentials-iot:ThingName}이 막아 주는 것","slug":"정책-변수-credentials-iot-thingname-이-막아-주는-것","link":"#정책-변수-credentials-iot-thingname-이-막아-주는-것","children":[]}]},{"level":2,"title":"5. 크로스 컴파일·리소스 제약·로그 레벨","slug":"_5-크로스-컴파일·리소스-제약·로그-레벨","link":"#_5-크로스-컴파일·리소스-제약·로그-레벨","children":[{"level":3,"title":"크로스 컴파일","slug":"크로스-컴파일","link":"#크로스-컴파일","children":[]},{"level":3,"title":"메모리·CPU 조정","slug":"메모리·cpu-조정","link":"#메모리·cpu-조정","children":[]},{"level":3,"title":"로그 레벨","slug":"로그-레벨","link":"#로그-레벨","children":[]},{"level":3,"title":"방화벽에 열어야 할 것","slug":"방화벽에-열어야-할-것","link":"#방화벽에-열어야-할-것","children":[]}]},{"level":2,"title":"다음 챕터","slug":"다음-챕터","link":"#다음-챕터","children":[]}]}],"git":{},"filePathRelative":"_study/webrtc/19-kvs-c-sdk.md"}');export{b as comp,g as data};
